mapper.select:
select travelTime, firstField, secondField, type from (
                  select create_time as travelTime, card_type as firstField, RIGHT(card_num,4) as secondField, 1 as type from opening_card_record where identity = #{customerIdentity}
                  union
                  select create_time as travelTime, product_name as firstField, concat(credit_amount,'元') as secondField, 2 as type from credit_record where identity = #{customerIdentity}
                  union
                  select visits_time as travelTime, visits_manager_code as firstField, null as secondField, 3 as type from customer_visits   where identity = #{customerIdentity}
              ) as travel_info
order by travelTime desc
